import{_ as n,a0 as p,w as d,s as g,I as a,x as s,a1 as l,A as t,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"Vim-plug：极简 Vim 插件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"Vim-plug：极简 Vim 插件管理器 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim-plug：极简 Vim 插件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim-plug：极简 Vim 插件管理器 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager","title":"Vim-plug：极简 Vim 插件管理器","tag":"201806","desc":""},"relativePath":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md","filePath":"[post].md"}'),r={name:"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md"};function h(u,i,m,k,b,c){const e=p("Link");return d(),g("div",null,[i[20]||(i[20]=a("h1",{id:"vim-plug-极简-vim-插件管理器",tabindex:"-1"},[s("Vim-plug：极简 Vim 插件管理器 "),a("a",{class:"header-anchor",href:"#vim-plug-极简-vim-插件管理器","aria-label":"Permalink to “Vim-plug：极简 Vim 插件管理器”"},"​")],-1)),i[21]||(i[21]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/06/vim-plug-720x340.png",alt:""})],-1)),a("p",null,[i[1]||(i[1]=s("当没有插件管理器时，Vim 用户必须手动下载 tarball 包形式的插件，并将它们解压到 ",-1)),i[2]||(i[2]=a("code",null,"~/.vim",-1)),i[3]||(i[3]=s(" 目录中。在少量插件的时候可以。但当他们安装更多的插件时，就会变得一团糟。所有插件文件分散在单个目录中，用户无法找到哪个文件属于哪个插件。此外，他们无法找到他们应该删除哪个文件来卸载插件。这时 Vim 插件管理器就可以派上用场。插件管理器将安装插件的文件保存在单独的目录中，因此管理所有插件变得非常容易。我们几个月前已经写了关于 ",-1)),l(e,{href:"https://linux.cn/article-9416-1.html"},{default:t(()=>[...i[0]||(i[0]=[s("Vundle",-1)])]),_:1}),i[4]||(i[4]=s(" 的文章。今天，我们将看到又一个名为 “Vim-plug” 的 Vim 插件管理器。",-1))]),i[22]||(i[22]=o(`<p>Vim-plug 是一个自由、开源、速度非常快的、极简的 vim 插件管理器。它可以并行地安装或更新插件。你还可以回滚更新。它创建<ruby>浅层克隆<rt>shallow clone</rt></ruby>最小化磁盘空间使用和下载时间。它支持按需加载插件以加快启动时间。其他值得注意的特性是支持分支/标签/提交、post-update 钩子、支持外部管理的插件等。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3><p>安装和使用起来非常容易。你只需打开终端并运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fLo ~/.vim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><p>Neovim 用户可以使用以下命令安装 Vim-plug：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fLo ~/.config/nvim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><h4 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to “安装插件”">​</a></h4><p>要安装插件，你必须如下所示首先在 Vim 配置文件中声明它们。一般 Vim 的配置文件是 <code>~/.vimrc</code>，Neovim 的配置文件是 <code>~/.config/nvim/init.vim</code>。请记住，当你在配置文件中声明插件时，列表应该以 <code>call plug#begin(PLUGIN_DIRECTORY)</code> 开始，并以 <code>plug#end()</code> 结束。</p><p>例如，我们安装 “lightline.vim” 插件。为此，请在 <code>~/.vimrc</code> 的顶部添加以下行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>call plug#begin(&#39;~/.vim/plugged&#39;)</span></span>
<span class="line"><span>Plug &#39;itchyny/lightline.vim&#39;</span></span>
<span class="line"><span>call plug#end()</span></span></code></pre></div><p>在 vim 配置文件中添加上面的行后，通过输入以下命令重新加载：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:source ~/.vimrc</span></span></code></pre></div><p>或者，只需重新加载 Vim 编辑器。</p><p>现在，打开 vim 编辑器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim</span></span></code></pre></div><p>使用以下命令检查状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugStatus</span></span></code></pre></div><p>然后输入下面的命令，然后按回车键安装之前在配置文件中声明的插件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugInstall</span></span></code></pre></div><h4 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to “更新插件”">​</a></h4><p>要更新插件，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugUpdate</span></span></code></pre></div><p>更新插件后，按下 <code>d</code> 查看更改。或者，你可以之后输入 <code>:PlugDiff</code>。</p><h4 id="审查插件" tabindex="-1">审查插件 <a class="header-anchor" href="#审查插件" aria-label="Permalink to “审查插件”">​</a></h4><p>有时，更新的插件可能有新的 bug 或无法正常工作。要解决这个问题，你可以简单地回滚有问题的插件。输入 <code>:PlugDiff</code> 命令，然后按回车键查看上次 <code>:PlugUpdate</code>的更改，并在每个段落上按 <code>X</code> 将每个插件回滚到更新前的前一个状态。</p><h4 id="删除插件" tabindex="-1">删除插件 <a class="header-anchor" href="#删除插件" aria-label="Permalink to “删除插件”">​</a></h4><p>删除一个插件删除或注释掉你以前在你的 vim 配置文件中添加的 <code>plug</code> 命令。然后，运行 <code>:source ~/.vimrc</code> 或重启 Vim 编辑器。最后，运行以下命令卸载插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugClean</span></span></code></pre></div><p>该命令将删除 vim 配置文件中所有未声明的插件。</p><h4 id="升级-vim-plug" tabindex="-1">升级 Vim-plug <a class="header-anchor" href="#升级-vim-plug" aria-label="Permalink to “升级 Vim-plug”">​</a></h4><p>要升级vim-plug本身，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugUpgrade</span></span></code></pre></div><p>如你所见，使用 Vim-plug 管理插件并不难。它简化了插件管理。现在去找出你最喜欢的插件并使用 Vim-plug 来安装它们。</p><p>就是这些了。我将很快在这里发布另一个有趣的话题。在此之前，请继续关注我们。</p><p>干杯!</p><hr>`,37)),a("p",null,[i[6]||(i[6]=s("via: ",-1)),l(e,{href:"https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/"},{default:t(()=>[...i[5]||(i[5]=[s("https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/",-1)])]),_:1})]),a("p",null,[i[11]||(i[11]=s("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...i[7]||(i[7]=[s("SK",-1)])]),_:1}),i[12]||(i[12]=s(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[8]||(i[8]=[s("lujun9972",-1)])]),_:1}),i[13]||(i[13]=s(" 译者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:t(()=>[...i[9]||(i[9]=[s("geekpi",-1)])]),_:1}),i[14]||(i[14]=s(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[10]||(i[10]=[s("wxy",-1)])]),_:1})]),a("p",null,[i[17]||(i[17]=s("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[15]||(i[15]=[s("LCTT",-1)])]),_:1}),i[18]||(i[18]=s(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...i[16]||(i[16]=[s("Linux中国",-1)])]),_:1}),i[19]||(i[19]=s(" 荣誉推出",-1))])])}const C=n(r,[["render",h]]);export{V as __pageData,C as default};
